const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries for San Jose and Los Angeles
  const sanJose = ee.Geometry.Point([-121.8863, 37.3382]);
  const losAngeles = ee.Geometry.Point([-118.2437, 34.0522]);

  // Create buffer regions (10km radius)
  const sanJoseRegion = sanJose.buffer(10000);
  const laRegion = losAngeles.buffer(10000);

  // 2. Date range
  const startDate = '2018-01-01';
  const endDate = '2019-12-31';

  // 3. Load Sentinel-5P NO2 collection
  const no2Collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select('tropospheric_NO2_column_number_density')
    .filterDate(startDate, endDate);

  // Filter for each location
  const sanJoseCol = no2Collection.filterBounds(sanJoseRegion);
  const laCol = no2Collection.filterBounds(laRegion);

  // Check collection sizes
  const sjSize = sanJoseCol.size().getInfo();
  const laSize = laCol.size().getInfo();

  console.log(`San Jose images: ${sjSize}`);
  console.log(`Los Angeles images: ${laSize}`);

  if (sjSize === 0 || laSize === 0) {
    console.log('No data available for one or both cities.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Apply quality masking and calculate mean
  function maskQuality(image) {
    const qa = image.select('qa_value');
    const mask = qa.gte(0.5);
    return image.updateMask(mask);
  }

  const sanJoseColMasked = sanJoseCol.map(maskQuality);
  const laColMasked = laCol.map(maskQuality);

  // Create mean composites
  const sanJoseMean = sanJoseColMasked.mean();
  const laMean = laColMasked.mean();

  // 5. Calculate regional statistics
  const sjStats = sanJoseMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: sanJoseRegion,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const laStats = laMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: laRegion,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const sjMeanValue = sjStats['tropospheric_NO2_column_number_density_mean'];
  const sjCount = sjStats['tropospheric_NO2_column_number_density_count'];
  const laMeanValue = laStats['tropospheric_NO2_column_number_density_mean'];
  const laCount = laStats['tropospheric_NO2_column_number_density_count'];

  console.log(`San Jose: Mean NO2 = ${sjMeanValue}, Valid pixels = ${sjCount}`);
  console.log(`Los Angeles: Mean NO2 = ${laMeanValue}, Valid pixels = ${laCount}`);

  // 6. Validation and answer
  if (sjCount === 0 || laCount === 0) {
    console.log('No valid pixels after quality masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (sjMeanValue === null || sjMeanValue === undefined || 
      laMeanValue === null || laMeanValue === undefined ||
      isNaN(sjMeanValue) || isNaN(laMeanValue)) {
    console.log('Calculation failed: Invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check reasonable range (0 to 0.001 mol/m²)
  if (sjMeanValue < 0 || sjMeanValue > 0.001 || laMeanValue < 0 || laMeanValue > 0.001) {
    console.log('Values outside expected range.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (sjMeanValue > laMeanValue) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
